            (c for rr in range(group[0], group[1] + 1)
             for c, v in enumerate(grid[rr]) if v != bg),
            default=-1
        )

    # Extend the copy that stops earlier, using the farther-right copy as a
    # guide. Only the newly extended portion is recolored.
    for i, a in enumerate(groups):
        for b in groups[i + 1:]:
            ha = a[1] - a[0] + 1
            hb = b[1] - b[0] + 1
            if ha != hb:
                continue

            ma, mb = rightmost(a), rightmost(b)
            if ma == mb:
